// Cura's 771 setting definitions (fdmprinter + fdmextruder) and its XML material key table, generated by
// tools/catalogue/cura.ts (PRF-17). The data's `notice` carries its LGPL licence.
import type { CatalogueFile, NativeKey } from './entry.ts';
import data from './data/cura.json' with { type: 'json' };

/** Where one fdm_materials XML element lands: a Material entity field, or a setting (a unified catalogue key). */
export interface CuraMaterialKey {
  /** Material entity field, dotted (`external_ids.cura_guid`). Set for elements that are not settings. */
  field?: string;
  /** Unified catalogue key of the setting the element sets (an Orca key or `cura.` key). */
  setting?: string;
  /** The Cura setting XmlMaterialProfile maps the element to. */
  cura?: string;
  provenance: string;
}

/**
 * `entries`: the `cura.` keys with no Orca equivalent. `names`: the Cura name of each canonical (Orca) key Cura has,
 * to merge as `native.cura` into the Orca catalogue. `per_extruder`: every Cura key resolved per extruder
 * (in fdmextruder.def.json or `settable_per_extruder`). `material`: XML element path (`properties/density`,
 * `settings/print temperature`) to where it lands. Defaults that are Cura formulas are `{expr}`, verbatim.
 */
export interface CuraCatalogueFile extends CatalogueFile {
  names: { [unified: string]: NativeKey };
  per_extruder: string[];
  material: { [xmlPath: string]: CuraMaterialKey };
}

export const curaCatalogue = data as CuraCatalogueFile;
